  //CORREGIDO PARA QA (19/10/2026): en QA el atributo "pais" de la identidad llega nulo porque la regla
  //BancoBase-IdentityMap-MX que lo calcula aun no existe en QA. Antes, tempPais.equalsIgnoreCase("MX")
  //lanzaba NullPointerException y la regla truena en TODA operacion (incluido Unlock) antes de llegar
  //al conector. Ahora, si "pais" es nulo se conserva el valor por default ("mexico", linea de arriba).
  String paisIdentidad = identity.getStringAttribute("pais");

  if(paisIdentidad != null){

    tempPais = paisIdentidad;

    if(tempPais.equalsIgnoreCase("MX")){

      tempPais = "mexico";           

    }

  }


   String applicationName = application.getName();

  //CORREGIDO PARA QA: en producción esta inicialización del logger estaba condicionada a que
  //applicationName fuera exactamente "BancoBase-Application-DirectorioActivo". En QA la aplicación
  //se llama "Active Directory - QA", por lo que la condición nunca se cumplía, "log" quedaba null,
  //y la primera llamada a log.debug() de la regla (mas abajo) lanzaba NullPointerException,
  //dejando la regla completamente inoperante. Se quita la condición para que el logger siempre
  //se inicialice sin importar el nombre de la aplicación.
  log = LogFactory.getLog("rule.bancobase.activedirectory");

  private String fixStringDate(String stringDate){

    log.debug("Entrando a fixStringDate");

    stringDate = stringDate.trim();

    String newStringDate = ""; //Valor a regresar

    //Primero, quitamos todos los espacios por "/"
    stringDate= stringDate.replace(" ", "/");

    log.debug("Valor de la cadena despues de quitar espacios: " + stringDate);

    stringDate= stringDate.replace(":", "/");

    log.debug("Valor de la cadena despues de quitar los dos puntos: " + stringDate);

    String[] arrayTest = stringDate.split("[/]");

    log.debug("Procesamos la cadena...");

    for(int i = 0; i < arrayTest.length ; i++) {

      String testTemp = "";

      testTemp = arrayTest[i];

      if(testTemp.length() >= 2) {

        newStringDate += testTemp;

      }else {

        String tempNumber = "";

        for(int y = 0 ; y < (2 - testTemp.length()) ; y++) {

          tempNumber += "0";

        }

        newStringDate += (tempNumber + testTemp); 

      }

    }

    log.debug("newStringDate: " + newStringDate);

    log.debug("Saliendo de fixStringDate");

    return newStringDate;

  }

  private String getAccountCurrentValue(Identity identity, String attributeName, String nativeIdentity){

    log.debug("Entrando a getAccountCurrentValue");

    String val = null;
    String currentNativeIdentity = "";

    log.debug("applicationName: " + applicationName);

    Application app = context.getObjectByName(Application.class,applicationName);

    IdentityService ids = new IdentityService(context);

    List links = ids.getLinks(identity,app);

    if(links.isEmpty()){

      log.debug("La identidad no tiene cuentas del aplicativo!");

    }

    if(links.size()==1){

      log.debug("Solo tiene una cuenta");

      currentNativeIdentity = links.get(0).getNativeIdentity();

      if(currentNativeIdentity.equalsIgnoreCase(nativeIdentity)){
        //Aqui encontramos la cuenta de la cual queremos obtener el valor

        log.debug("nativeIdentity encontrado: " + currentNativeIdentity);

        Object tempValue = links.get(0).getAttribute(attributeName);

        if(tempValue != null){

          val = (String) links.get(0).getAttribute(attributeName);

          log.debug("Valor del atributo encontrado: " + val);


        }else{

          log.debug("Valor del atributo no encontrado!");

        }


      }else{
        //No hay cuenta con el valor que queremos obtener
        log.debug("nativeIdentity no encontrado!");

      }

    }else if(links.size()>1){

      //Si son muchas cuentas, buscamos la que coincida con nativeIdentity
      log.debug("La identidad tiene mas de una cuenta del aplicativo!"); 

      for(Link link : links){

        currentNativeIdentity = link.getNativeIdentity();

        if(currentNativeIdentity.equalsIgnoreCase(nativeIdentity)){

          log.debug("nativeIdentity encontrado: " + currentNativeIdentity);

          Object tempValue = link.getAttribute(attributeName);

          if(tempValue != null){

            val = (String) link.getAttribute(attributeName);

            log.debug("Valor del atributo encontrado: " + val);

            //salimos del bucle
            break;

          }else{

            log.debug("Valor del atributo no encontrado!");

          }

        }

      }

    }


    log.debug("Valor del atributo: " + val );

    log.debug("Saliendo de getAccountCurrentValue");

    return val;

  }

  private String[] generateDN(Identity identity){

    log.debug("Entrando a generateDN"); 

    //Para obtener paises validos
    List appListCountries = null;
    Custom customObjectCountries = null;
    boolean validCountry = false;

    String foundOU = null;

    String prefix = "";
    String lastName = "";
    String apellidoMaterno = "";
    String firstName = "";
    String customObjectName = "";
    String internalCustomObjectName = "";
    String externalCustomObjectName = "";
    String employeeType = ""; 

    //Agregado 04/01/21
    String pais = "";
    String newValueStandar = ""; 

    String calculatedDN = "";
    String calculatedCN = "";

    String[] data = {"",""};

    //Obtenemos los datos de la identidad para el CN

    prefix = "CN=";
    lastName = identity.getStringAttribute("lastname");
    apellidoMaterno = identity.getStringAttribute("second_last_name");
    firstName = identity.getStringAttribute("firstname");
    employeeType = identity.getType();
    pais= identity.getStringAttribute("pais");

    boolean administratorOUflag = false;

    log.debug("Prefix: " + prefix);
    log.debug("LastName: " + lastName);
    log.debug("ApellidoMaterno: " + apellidoMaterno);
    log.debug("FirstName: " + firstName);
    log.debug("EmployeeType: " + employeeType);
    log.debug("pais: " + pais);

    //Esta validacion obtiene los paises validos por dominio

    customObjectCountries= context.getObjectByName(Custom.class, applicationName + "_Valid_Countries");

    if(customObjectCountries== null) {

      log.debug(applicationName + "_Valid_Countries (Custom Object) no existe!");

    }else{

      log.debug(applicationName + "_Valid_Countries (Custom Object) existe!");

      //Se obtiene una lista del custom object
      appListCountries= (List) customObjectCountries.get("Valid Countries");

      log.debug("Imprimiendo paises validos: ");

      for(int y = 0; y < appListCountries.size() ; y++ ) {

        log.debug("Indice "+ y + " pais valido: " + appListCountries.get(y).toString());

      }

    }

    ////Validamos que en la lista venga el pais

    for(int i = 0 ; i < appListCountries.size() ; i++){

      String tempCountry = "";
      tempCountry = appListCountries.get(i).toString();

      if(tempCountry.equalsIgnoreCase(pais) ){

        validCountry = true;
        break;

      }

    }

    if(special){

      log.debug("Para " + applicationName);

      if(!validCountry){

        log.debug("El pais " + pais + " pertence al dominio.");

      }else{

        log.debug("El pais " + pais + " no pertence al dominio!");
        log.debug("Si la identidad es contractor especial, se utilizaran criterios de asignacion diferentes.");
        administratorOUflag = true;

      }

    }else{

      if(validCountry){

        log.debug("El pais " + pais + " pertence al dominio.");

      }else{

        log.debug("El pais " + pais + " no pertence al dominio!");
        log.debug("Si la identidad es contractor especial, se utilizaran criterios de asignacion diferentes.");
        administratorOUflag = true;

      }

    }


    //Agregado 04/01/21
    //Obtenemos los valores por pais
    //Valor de la OU por default (por pais)
    //Valor de Custom Object para buscar por criterios de asignaci n
    ///Para custom object de employee
    String codigoEmployeeOUpaisKey = "";

    if(administratorOUflag){

      codigoEmployeeOUpaisKey= "employeedomain"+ADSufix+"oupais";

    }else{

      if(ADAbvoSpecial){

	      codigoEmployeeOUpaisKey= ADSufix+"employeeoupais";       

      }else{

	      codigoEmployeeOUpaisKey= "employeeoupais";        

      }

    }

    log.debug("codigoEmployeeOUpaisKey: " + codigoEmployeeOUpaisKey);

    internalCustomObjectName = getValueFromCountryData(identity,codigoEmployeeOUpaisKey);

    log.debug("internalCustomObjectName: " + internalCustomObjectName);

    ///Para custom object de contractor
    String codigoContractorOUpaisKey= "";

    if(administratorOUflag){

      codigoContractorOUpaisKey = "contractordomain"+ADSufix+"oupais";

    }else{

      if(ADAbvoSpecial){

	      codigoContractorOUpaisKey = ADSufix+"contractoroupais";


      }else{

	      codigoContractorOUpaisKey = "contractoroupais";       

      }

    }

    log.debug("codigoContractorOUpaisKey: " + codigoContractorOUpaisKey);

    externalCustomObjectName = getValueFromCountryData(identity,codigoContractorOUpaisKey);

    log.debug("externalCustomObjectName: " + externalCustomObjectName);


    //Validaciones
    if(internalCustomObjectName != "" && internalCustomObjectName != null){

      log.debug("Custom object para buscar criterio de asignacion de OU para empleados: " + internalCustomObjectName); 

    }else{

      log.debug("El Custom Object para buscar criterio de asignacion de OU para empleados no fue encontrado o no pudo ser generado!");


    }

    if(externalCustomObjectName != "" && externalCustomObjectName != null){

      log.debug("Custom Object para buscar criterio de asignacion de OU para contractors: " + externalCustomObjectName); 

    }else{

      log.debug("El Custom Object para buscar criterio de asignacion de OU para contractors no fue encontrado o no pudo ser generado!");

    }


    //Obtenemos el valor del custom object
    if(employeeType.equalsIgnoreCase("employee")){

      customObjectName = internalCustomObjectName;

      log.debug("Calculando el DN para el empleado interno consumiendo el custom object " + customObjectName);

    }else{

      customObjectName = externalCustomObjectName;

      log.debug("Calculando el DN para el empleado externo consumiendo el custom object " + customObjectName);

    }

    foundOU = getValueFromCountryDataMapping(identity, customObjectName);

    //En este punto validamos el valor de la OU encontrada, en caso de no encontar nada, se regresa el default
    log.debug("Valor de OU despues de la busqueda: " + foundOU);

    //Concatenamos los valores del DN
    //Agregado 240320
    if(foundOU != null && !(foundOU.equalsIgnoreCase(""))){

      calculatedDN = foundOU;

    } 

    if(apellidoMaterno == null){

      calculatedCN = new StringBuffer(prefix).append(lastName).append("\\, ").append(firstName).toString();

    }else{

      calculatedCN = new StringBuffer(prefix).append(lastName).append(" ").append(apellidoMaterno).append("\\, ").append(firstName).toString();


    }

    log.debug("CN calculado: " + calculatedCN);
    log.debug("DN calculado: " + calculatedDN);

    data[0] = calculatedCN; 
    data[1] = calculatedDN;

    log.debug("Saliendo de generateDN");

    return data;

  }

  private String generateEmail(Identity identity, String ou, String indentityEmail) {

    log.debug("Entrando a generateEmail"); 

    String firstname= identity.getStringAttribute("firstname");
    String lastname= identity.getStringAttribute("lastname");
    String apellidomaterno = identity.getStringAttribute("second_last_name");

    String mailContext = "";
    String type= identity.getType(); 
    String pais= identity.getStringAttribute("pais");
    String prefixPais= "tmp";

    String[] tempArrayFirstname = null;
    String[] tempArrayLastname = null;
    String[] tempArrayApellidomaterno = null;

    List arrayFirstname = null;
    List arrayLastname = null;
    List arrayApellidomaterno = null;
    List arrayLastnames = null;

    String tempName = "";
    String charRestLastnamesMerge = "";

    int dataMinSize = 1;

    //Variables de conexion
    String authenticationType = "";
    String authorizationType = "";
    String domainDN = "";
    String forestName = "";
    String password = "";
    String port = "";
    List servers = new ArrayList();
    String singleServer = "";
    String user = "";
    String credentials = "";
    //Prueba SSL DAA 170123
    boolean sslCheck = false;
    String sslSufix = "";
    String url = "";


    log.debug("mailContext: " + mailContext);
    log.debug("firstname: " + firstname); 
    log.debug("type: " + type);
    log.debug("lastname: " + lastname);
    log.debug("apellidomaterno: " + apellidomaterno);
    log.debug("pais: " + pais);
    log.debug("prefixPais (TMP): " + prefixPais);
    log.debug("OU: " + ou);
    log.debug("Current identity mail: " + indentityEmail);
    log.debug("dataMinSize: " + dataMinSize); 

    String objectEmail; //No inicializar

    List arrayEmails = new ArrayList();

    //A adido para evitar homonimos
    int consecutiveMaxNumber = 9;
    String lastArrayEmail = ""; 

    ////////////////////////////
    //Cambio de logica para el calculo de upn/mail
    log.debug("Comenzamos con la conversion de atributos y los email/UPN posibles..");
    log.debug("Conversion de firstname: " + firstname);

    //Convertimos el nombre a minusculas y quitamos posibles espacio en blanco al principio y al final
    firstname = firstname.trim().toLowerCase();

    //Agregado para cambiar remocion de caracteres
    firstname = removeConvertSpecialCharacteres(firstname);

    //Buscamos los valores para el arreglo de nombres
    tempArrayFirstname = firstname.split("[ ]");

    arrayFirstname = new ArrayList();

    if(ADAbvoSpecial){

      log.debug("Para " + applicationName);

      mailContext = "@bancobase.com";

      for(int i = 0 ; i < tempArrayFirstname.length ; i++){

        String tempData = "";
        tempData = tempArrayFirstname[i];

        //////////////
        //si la encuentra le suma el siguiente nombre
        if(i < tempArrayFirstname.length -1){ //no va a buscar nombres compuestos si el dato esta en la ultima posicion del arreglo

          //si la encuentra le suma el siguiente nombre
          if (verifyData(tempData, "v")) { // se envia "v" para verificar nombre compuesto

            log.debug("Palabra detectada como preposicion: " + tempData);
            //Como pueden existir mas de una preposcion, buscamos en el resto de arreglo
            int ix = 0;

            for(int w = i+1 ; w < tempArrayFirstname.length ; w++){
              //Se empieza a buscar en la siguiente posicion

              String tempData2 = "";
              tempData2 = tempArrayFirstname[w];

              if (verifyData(tempData2, "v")) {
                //Si es preposicion se anade tambien
                log.debug("Palabra detectada como preposicion: " + tempData2);
                tempData += tempData2;

                ix++; // se incrementa para que i del principal no tome la palabra encontrada

              }else{

                //en este punto, la palabra ya no es preposcion
                //Sin embargo, si la anterior si lo fue, se anade a lo concatenacion
                //no va a buscar atraz si esta en la posicion 0

                if(w !=0) {

                  if (verifyData(tempArrayFirstname[w - 1], "v")) {

                    tempData += tempData2;

                    ix++;

                  }

                }

              }

            }

            //a i principal se le suman las posiciones ya encontradas
            i += ix;

            log.debug("El nombre compuesto es: " + tempData);

          }

        }

        //////////////

        if(tempData.length() > dataMinSize){

          if(!verifyData(tempData, "r")){ //Aqui se verifica contra el diccionario de datos, debe regresar falso para a adirlo al array

            //Aqui todo se cumplio, se aniade al array
            arrayFirstname.add(tempData);

          }else{

            log.debug("Nombre descartado por estar en diccionario de datos: " + tempData);

          }

        }else{

          log.debug("Nombre descartado por longitud minima o estar vacio: " + tempData);

        }

      }

    }else{ 

      mailContext= "bancobase.com";

      for(int i = 0 ; i < tempArrayFirstname.length ; i++){

        String tempData = "";
        tempData = tempArrayFirstname[i];

        if(tempData.length() > dataMinSize){

          if(!verifyData(tempData, "r")){ //Aqui se verifica contra el diccionario de datos, debe regresar falso para a adirlo al array

            //Aqui todo se cumplio, se aniade al array
            arrayFirstname.add(tempData);

          }else{

            log.debug("Nombre descartado por estar en diccionario de datos: " + tempData);

          }

        }else{

          log.debug("Nombre descartado por longitud minima o estar vacio: " + tempData);

        }

      }

    }
    //Aqui ya tenemos el arreglo con todos los nombres
    log.debug("Total de nombres detectados: ");

    for(int x = 0; x < arrayFirstname.size() ; x++) {

      log.debug("-> " + arrayFirstname.get(x));

    }

    //Aqui ya tenemos los nombres
    //Ahora empezamos con los apellidos

    //Apellido paterno siempre es mandatorio
    //Obtenemos el primer apellido y el resto de apellidos

    log.debug("Conversion de lastname: " + lastname);

    lastname = lastname.trim().toLowerCase();
    lastname = removeConvertSpecialCharacteres(lastname);

    tempArrayLastname = lastname.split("[ ]"); ///

    arrayLastname = new ArrayList();

    if(ADAbvoSpecial){

      log.debug("Para " + applicationName);

      for(int i = 0 ; i < tempArrayLastname.length ; i++){

        String tempData = "";
        tempData = tempArrayLastname[i];

        //////////
        //Aqui entra la validacion de apellidos compuestos

        if(i < tempArrayLastname.length -1){ //no va a buscar apellidos compuestos si el dato esta en la ultima posicion del arreglo

          //si la encuentra le suma el siguiente apellido
          if (verifyData(tempData, "v")) { // se envia "v" para verificar apellido compuesto

            log.debug("Palabra detectada como preposicion: " + tempData);
            //Como pueden existir mas de una preposcion, buscamos en el resto de arreglo
            int ix = 0;

            for(int w = i+1 ; w < tempArrayLastname.length ; w++){
              //Se empieza a buscar en la siguiente posicion

              String tempData2 = "";
              tempData2 = tempArrayLastname[w];

              if (verifyData(tempData2, "v")) {
                //Si es preposicion se anade tambien
                log.debug("Palabra detectada como preposicion: " + tempData2);
                tempData += tempData2;

                ix++; // se incrementa para que i del principal no tome la palabra encontrada

              }else{

                //en este punto, la palabra ya no es preposcion
                //Sin embargo, si la anterior si lo fue, se anade a lo concatenacion
                //no va a buscar atraz si esta en la posicion 0

                if(w !=0) {

                  if(verifyData(tempArrayLastname[w - 1], "v")) {

                    tempData += tempData2;

                    ix++;

                  }

                }

              }

            }

            //a i principal se le suman las posiciones ya encontradas
            i += ix;

            log.debug("El apellido paterno compuesto es: " + tempData);

          }

        }
        //////////

        if(tempData.length() > dataMinSize){

          if(!verifyData(tempData, "r")){ //Aqui se verifica contra el diccionario de datos, debe regresar falso para a adirlo al array

            //Aqui todo se cumplio, se aniade al array
            arrayLastname.add(tempData);

          }else{

            log.debug("Apellido paterno descartado por estar en diccionario de datos: " + tempData);

          }

        }else{

          log.debug("Apellido paterno descartado por longitud minima o estar vacio: " + tempData);

        }

      }

    }else{

      for(int i = 0 ; i < tempArrayLastname.length ; i++){

        String tempData = "";
        tempData = tempArrayLastname[i];

        //Aqui entra la validacion de apellidos compuestos

        if(i < tempArrayLastname.length -1){ //no va a buscar apellidos compuestos si el dato esta en la ultima posicion del arreglo

          //si la encuentra le suma el siguiente apellido
          if (verifyData(tempData, "v")) { // se envia "v" para verificar apellido compuesto

            log.debug("Apellido paterno detectado como compuesto: " + tempData);

            tempData += tempArrayLastname[i + 1];

            log.debug("El apellido paterno compuesto es: " + tempData);

            i++; //Se aumenta en el contador para no tomar el siguiente dato

          }

        } 

        if(tempData.length() > dataMinSize){

          if(!verifyData(tempData, "r")){ //Aqui se verifica contra el diccionario de datos, debe regresar falso para a adirlo al array

            //Aqui todo se cumplio, se aniade al array
            arrayLastname.add(tempData);

          }else{

            log.debug("Apellido paterno descartado por estar en diccionario de datos: " + tempData);

          }

        }else{

          log.debug("Apellido paterno descartado por longitud minima o estar vacio: " + tempData);

        }

      }

    }

    //Aqui ya tenemos el arreglo con todos los nombres
    log.debug("Total de apellidos paternos detectados: ");

    for(int x = 0; x < arrayLastname.size() ; x++) {

      log.debug("-> " + arrayLastname.get(x));

    }

    //ahora para el apellido materno
    if(apellidomaterno != null) {

      log.debug("Ya que apellido materno no es nulo, lo utilizaremos como extra para el resto de apellidos...");

      log.debug("Conversion de apellidomaterno: " + apellidomaterno);

      apellidomaterno = apellidomaterno.trim().toLowerCase();
      apellidomaterno = removeConvertSpecialCharacteres(apellidomaterno);

      tempArrayApellidomaterno = apellidomaterno.split("[ ]");

      arrayApellidomaterno = new ArrayList();

      if(ADAbvoSpecial){

        log.debug("Para " + applicationName);

        for(int i = 0 ; i < tempArrayApellidomaterno.length ; i++){

          String tempData = "";
          tempData = tempArrayApellidomaterno[i];

          if(i < tempArrayApellidomaterno.length -1){ //no va a buscar apellidos compuestos si el dato esta en la ultima posicion del arreglo

            log.debug("Palabra detectada como preposicion: " + tempData);
            //Como pueden existir mas de una preposcion, buscamos en el resto de arreglo
            int ix = 0;

            for(int w = i+1 ; w < tempArrayApellidomaterno.length ; w++){
              //Se empieza a buscar en la siguiente posicion

              String tempData2 = "";
              tempData2 = tempArrayApellidomaterno[w];

              if (verifyData(tempData2, "v")) {
                //Si es preposicion se anade tambien
                log.debug("Palabra detectada como preposicion: " + tempData2);
                tempData += tempData2;

                ix++; // se incrementa para que i del principal no tome la palabra encontrada

              }else{

                //en este punto, la palabra ya no es preposcion
                //Sin embargo, si la anterior si lo fue, se anade a lo concatenacion
                //no va a buscar atraz si esta en la posicion 0

                if(w !=0) {

                  if (verifyData(tempArrayApellidomaterno[w - 1], "v")) {

                    tempData += tempData2;

                    ix++;

                  }

                }

              }

            }

            //a i principal se le suman las posiciones ya encontradas
            i += ix;

            log.debug("El apellido paterno compuesto es: " + tempData);

          }
          /////

          if(tempData.length() > dataMinSize){

            if(!verifyData(tempData, "r")){ //Aqui se verifica contra el diccionario de datos, debe regresar falso para a adirlo al array

              //Aqui todo se cumplio, se aniade al array
              arrayApellidomaterno.add(tempData);

            }else{

              log.debug("Apellido materno descartado por estar en diccionario de datos: " + tempData);

            }

          }else{

            log.debug("Apellido materno descartado por longitud minima o estar vacio: " + tempData);

          }

        }

      }else{

