      log.debug("Combinacion " + (i+1) + " de UPN a buscar: " + arrayEmails.get(i) );

      String attributeToSearch = "";

      attributeToSearch = arrayEmails.get(i).toString();

      for(int y = 0 ; y < listDomains.size() ; y++) {

        Map mainMap = new HashMap();

        mainMap = (Map) listDomains.get(y);

        domainDN = (String) mainMap.get("domainDN");

