        authenticationType = (String) mainMap.get("authenticationType");
        authorizationType = (String) mainMap.get("authorizationType");

        forestName = (String) mainMap.get("forestName");
        password = (String) mainMap.get("password");
        port = (String) mainMap.get("port");
        servers = (List) mainMap.get("servers");
        singleServer = servers.get(0).toString();
        user = (String) mainMap.get("user"); 
        credentials = context.decrypt(password);
      	sslCheck = mainMap.get("useSSL");      

        domainToSearch = domainDN;

        //DEBUG
        log.debug("authenticationType: " + authenticationType);
        log.debug("authorizationType: " + authorizationType);

        log.debug("forestName: " + forestName);
        log.debug("password: " + password);
        log.debug("port: " + port);
        log.debug("singleServer: " + singleServer);
        log.debug("user: " + user); 
        log.debug("credentials: " + credentials);
        log.debug("domainToSearch: " + domainToSearch);

		    log.debug("SSL: " + sslCheck);

        if(sslCheck){
        sslSufix = "s";
        }      

        url = "ldap"+sslSufix+"://" + singleServer + ":" + port;
        log.debug("URL: " + url);         

        env.put(Context.INITIAL_CONTEXT_FACTORY,"com.sun.jndi.ldap.LdapCtxFactory");
        env.put(Context.PROVIDER_URL, url); 
        env.put(Context.SECURITY_PRINCIPAL,user);
        env.put(Context.SECURITY_CREDENTIALS,credentials);
        env.put(Context.SECURITY_AUTHENTICATION,authenticationType);

        List returnList = new ArrayList();

        SearchControls searchCtls = new SearchControls();
        searchCtls.setReturningAttributes(Util.csvToArray("distinguishedName"));
        searchCtls.setSearchScope(SearchControls.SUBTREE_SCOPE);

        LdapContext ctgxGC = null;

        try{

          ctgxGC = new InitialLdapContext(env,null);
          String searchFilter = "(&(objectClass=user)(userPrincipalName="+attributeToSearch+"))";

          NamingEnumeration answer = ctgxGC.search(domainToSearch, searchFilter, searchCtls);
          //Check if unique

          if(!answer.hasMoreElements()) {
            //Si entra aqui es porque no lo encontro!
            //objectEmail = attributeToSearch;

            log.debug("UPN [" + attributeToSearch + "] no encontrado en el dominio [" + domainToSearch + "]");

            //break;

          }else{

            Attributes attrs = ( (SearchResult) answer.next() ).getAttributes();
            Attribute attr = attrs.get("distinguishedName");
            String dnFromAD = "";

            if(attr != null){

              dnFromAD = (String) attr.get();

            }

            log.debug("UPN [" + attributeToSearch + "] encontrado en el dominio [" + domainToSearch + "] en la cuenta [" + dnFromAD + "]");

            existenceCounter++;

          }

        }catch (NamingException e){

          log.debug("Error: " + e.toString());

        }finally{

          if (null != ctgxGC) {

            try{

              ctgxGC.close();

            }catch (NamingException e) {

              log.debug("Error: " + e.toString()); 

            }

          }

        } 

      }

      //Aqui ya termino de buscar en todos los dominios si el correo existe
      log.debug("En este punto ya termino de buscar en todos los dominios si el UPN existe");

      if(existenceCounter == 0){

        log.debug("Ya que el UPN no fue encontrado en ningun dominio, no es necesario buscar la siguiente combinacion."); 

        //Aqui no encontro el correo en ningun dominio
        objectEmail = attributeToSearch;
        break;

      }else{

        log.debug("Ya que el UPN fue encontrado " + existenceCounter +" veces, es necesario buscar la siguiente combinacion.");
        existenceCounter = 0;
      }

    }

    log.debug("UPN: " + objectEmail ); 

    log.debug("Saliendo de generateEmail");

    return objectEmail;

  }


  /**
* Busca un atributo en el Link pasado como par metro
*/
  private String getLinkValue(Log log, Link link, String attrName){
    log.debug("Inicia busqueda de atributo en objeto link");
    Object attributeValue = link.getAttribute(attrName); 
    String value = null;
    if (attributeValue!=null){
      if (attributeValue instanceof String){
        value = (String)attributeValue;
      } else if (attributeValue instanceof List){
        for (String each : (List) attributeValue){ 
          value=value+";"+each;
        }
      }else if (attributeValue instanceof Boolean){
        value=(String)attributeValue.toString();
      }
    }
    log.debug("Regresando valor encontrado"); 
    return value;
  }

  /**
* Inicia la lectura del samaccountname desde el Link de la aplicaci n de AD
* ligado a la identidad
*/
  private String getSamAccountNameFromADLink(Log log, String applicationName)
  {
    log.debug("Inicializando objetos para leer links");
    String samAccountName = null;

    Identity idenPlan = plan.getIdentity();
    Application app = context.getObjectByName(Application.class, applicationName);
    IdentityService tmpService = new IdentityService(context);
    if(null != app)
    {
      log.debug("Iterando links existentes");
      List links = tmpService.getLinks(idenPlan, app);
      if(null != links && links.size() == 1)
      {
        for(Link link: links)
        {
          String attributeValues = getLinkValue(log, link, "sAMAccountName");
          if(null != attributeValues)
          {
            String[] valuesList = attributeValues.split(";");
            samAccountName = valuesList[0];
          }
        }
      }
    }

    return samAccountName;
  }

  /**
* Busca en AD la cuenta pasada como par metro y regresa el valor del campo
* 'description' de la cuenta encontrada.
*/
  private String readCurrentDescriptionFromAD(Log log, String samAccountName, String nativeIdentity, String applicationName, String ou)
  {
    Custom customObject = null;
    List mainList = new ArrayList();
    String principalKey = "";
    String customObjectName = "";
    Object newObject = null;
    String newValue = "";

    principalKey = "Valid Domains";
    customObjectName = applicationName + "_Valid_Domains";

    String descFromAD = "";

    log.debug("Obteniendo lo dominios validos del custom object " + customObjectName );

    customObject = context.getObjectByName( Custom.class, 
                                           customObjectName);

    if (customObject != null) {

      newObject = customObject.get(principalKey);

      if(newObject != null) {

        if(newObject instanceof List) {

          log.debug("El CustomObject "+ customObjectName + " existe!");

          mainList = (List) customObject.get(principalKey);

          log.debug("Imprimiendo los dominios validos encontrados..");

          for(int i = 0 ; i < mainList.size() ; i++ ) {

            log.debug("Indice: " + i + " valor: " + mainList.get(i));

          }

          //A adido 1/10/20
          log.debug("Comenzamos a buscar entre los dominios...");

          String domainToSearch = "";

          for(int i = 0 ; i < mainList.size() ; i++ ) {

            String tempDomain = "";

            tempDomain = mainList.get(i);

            log.debug("Valor del dominio sin transformacion: " + tempDomain);

            int indexOf = -1;

            indexOf = tempDomain.indexOf("|");

            tempDomain = tempDomain.substring(indexOf + 1, tempDomain.length());

            log.debug("Valor del dominio con transformacion: " + tempDomain);

            if(ou.contains(tempDomain)){

              log.debug("Dominio encontrado!");

              domainToSearch = tempDomain;

              break;

            }

          }

          log.debug("Dominio a buscar en la configuraci n de la aplicacion: " + domainToSearch);

          log.debug( "Leyendo dominios configurados en la aplicacion: " + applicationName );
          Application app = context.getObjectByName(Application.class, applicationName);
          List listDomains = (List) app.getAttributeValue("domainSettings");

          log.debug( "Buscando datos de conexion al dominio de la cuenta: " + nativeIdentity );
          Hashtable env = new Hashtable();
          String domainFound = null;

          for(Map domainMap : listDomains){

            String appDomain = (String) domainMap.get("domainDN");

            if(domainToSearch.equalsIgnoreCase(appDomain)) {

              log.debug("Dominio encontrado: " + appDomain);
              domainFound = appDomain;

              String authenticationType = (String) domainMap.get("authenticationType");
              String port = ((String) domainMap.get("port"));
              String server = ((List) domainMap.get("servers")).get(0).toString();
              String user = (String) domainMap.get("user");
              String credentials = context.decrypt( (String) domainMap.get("password") );
              //Pruebas SSL DAA 160123
              boolean sslCheck = domainMap.get("useSSL");
              String sslSufix = "";
              String url = "";	

              log.debug("Datos de conexion leidos para el dominio");
              log.debug("authenticationType: " + authenticationType);
              log.debug("port: " + port);
              log.debug("server: " + server);
              log.debug("user: " + user);

              log.debug("SSL: " + sslCheck);

              if(sslCheck){
              sslSufix = "s";
              }

              url = "ldap"+sslSufix+"://" + server + ":" + port;
              log.debug("URL: " + url);               

              env.put(Context.INITIAL_CONTEXT_FACTORY,"com.sun.jndi.ldap.LdapCtxFactory");
	      			env.put(Context.PROVIDER_URL, url);
              env.put(Context.SECURITY_PRINCIPAL, user);
              env.put(Context.SECURITY_CREDENTIALS, credentials);
              env.put(Context.SECURITY_AUTHENTICATION, authenticationType);

              break;
            }
          }

          log.debug("Inicializando variables de busqueda"); 
          SearchControls searchCtls = new SearchControls();
          searchCtls.setReturningAttributes(Util.csvToArray("description"));
          searchCtls.setSearchScope(SearchControls.SUBTREE_SCOPE);

          log.debug("Buscando cuenta en AD de " +samAccountName);
          LdapContext ctgxGC = new InitialLdapContext(env,null);
          String searchFilter = "(&(objectClass=user)(sAMAccountName=" + samAccountName + "))";
          NamingEnumeration answer = ctgxGC.search(domainFound, searchFilter, searchCtls);

          log.debug("Validando respuesta de la busqueda");

          if(answer.hasMoreElements()) {

            Attributes attrs = ( (SearchResult) answer.next() ).getAttributes();
            Attribute attr = attrs.get("description");

            if(attr != null){

              descFromAD = (String) attr.get();

              log.debug("El valor de description para la cuenta en AD es: " + descFromAD);


            }else{

              log.debug("La cuenta no tiene valor en el atributo description!");

            }

          }else {

            log.debug("No se encontro una cuenta de AD con sAMAccountName: " + samAccountName);

          }

          ctgxGC.close();

        }else {

          log.debug("El objeto encontrado con la llave " + principalKey+ " no es una lista!");
          log.debug("El valor de description no sera insertado!");

        }

      }else {

        log.debug("El valor "+ principalKey+ " no existe como llave en el CustomObject " + customObjectName +"!");
        log.debug("El valor de description no sera insertado!");
      }

    }else {

      log.debug("El CustomObject "+ customObjectName + " no existe o esta vacio!");
      log.debug("El valor de description no sera insertado!");

    }


    return descFromAD;
  }

  /**
* Genera el nuevo valor para el campo description de AD concatenando al final
* del valor oldDescription, el valor generado.
*/
  private String generateDescription(Log log, String operation, String oldDescription)
  {
    String newDescription = "";

    log.debug("Inicializando mapa con codigos de operaciones para campo description");
    Map operations = new HashMap();
    operations.put( "Create", "A" );
    operations.put( "Disable", "B" );
    operations.put( "Modify", "C" );
    operations.put( "Enable", "C" );
    operations.put( "Unlock", "C" );
    operations.put( "Lock", "C" );
    log.debug("La operacion pasada como parametro es: " + operation);

    if(null == oldDescription || oldDescription.isEmpty())
    {
      log.debug("No hay valor actual para el campo description");
    }
    else
    {
      log.debug("El valor actual de description es: " + oldDescription);
      newDescription = oldDescription + "/";
    }

    SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd");
    newDescription = newDescription + "IDM " + ((String) operations.get(operation)) + " " + dateFormat.format(new Date());

    return newDescription;
  }

  private String removeConvertSpecialCharacteres(String data){

    //Caracteres a remover
    String[] characteresToRemove = {" ", " ", " ", " ","!", "\"", "#", "$", "%", 
                                    "&", "'", "(", ")", "*", "+", "-", "/", ":", ";", 
                                    "<", "=", ">", "?", "@","[", "\\", "]", "^", "_",
                                    "`","{", "}", "~", "+"," ", " ", " ", " ", " ",
                                    " ", " ", " ", " ", " ", " ", " ", " ", " ", " ", 
                                    " "," ", " ", " ", " ", " "," ", " ", " ", " ", " ", 
                                    " ", " ", " "," "," "," ", " ", " "," "," "," ",
                                    " "," ", " ", " ", " ", " ", " ", " ", " ", 
                                    " ", " ", " "," ", " ", " ", " ", " ", " "," ", 
                                    " ", " ",".",","};

    String[] upperA = {" ", " ", " ", " ", " ", " "}; 
    String[] lowerA = {" ", " ", " ", " ", " ", " "}; 
    String[] upperE = {" ", " ", " ", " "};
    String[] lowerE = {" ", " ", " ", " "};
    String[] upperO = {" ", " ", " ", " ", " "};
    String[] lowerO = {" ", " ", " ", " ", " "}; 
    String[] upperU = {" ", " ", " ", " "};
    String[] lowerU = {" ", " ", " ", " "};
    String[] upperI = {" ", " ", " ", " "};
    String[] lowerI = {" ", " ", " ", " "};
    String[] upperN = {" "};
    String[] lowerN = {" "};
    String[] upperY = {" ", " "};
    String[] lowerY = {" ", " "};

    String[] upperC = {" "};
    String[] lowerC = {" "}; 

    if(data == null){

      data = "";

    }


    //Primero hacemos un
    data = data.trim();

    //Primero, quitamos caracteres especiales

    for(int i = 0; i < characteresToRemove.length; i++){

      data = data.replace(characteresToRemove[i], "");

    }

    //ahora A mayuscula
    for(int i = 0; i < upperA.length; i++){

      data = data.replace(upperA[i], "A");

    }
    //ahora A minuscula
    for(int i = 0; i < lowerA.length; i++){

      data = data.replace(lowerA[i], "a");

    }
    //*****************************************
    //ahora E mayuscula
    for(int i = 0; i < upperE.length; i++){

      data = data.replace(upperE[i], "E");

    }
    //ahora E minuscula
    for(int i = 0; i < lowerE.length; i++){

      data = data.replace(lowerE[i], "e");

    }
    //*****************************************
    //ahora O mayuscula
    for(int i = 0; i < upperO.length; i++){

      data = data.replace(upperO[i], "O");

    }

    //ahora O minuscula
    for(int i = 0; i < lowerO.length; i++){

      data = data.replace(lowerO[i], "o");

    } 
    //****************************************
    //ahora U mayuscula
    for(int i = 0; i < upperU.length; i++){

      data = data.replace(upperU[i], "U");

    }
    //ahora U minuscula
    for(int i = 0; i < lowerU.length; i++){

      data = data.replace(lowerU[i], "u");

    } 
    //****************************************
    //ahora I mayuscula
    for(int i = 0; i < upperI.length; i++){

      data = data.replace(upperI[i], "I");

    }
    //ahora I lower
    for(int i = 0; i < lowerI.length; i++){

      data = data.replace(lowerI[i], "i");

    }
    //****************************************
    //ahora   mayuscula
    for(int i = 0; i < upperN.length; i++){

      data = data.replace(upperN[i], "N");

    }
    //ahora   minuscula
    for(int i = 0; i < lowerN.length; i++){

      data = data.replace(lowerN[i], "n");

    }
    //***************************************
    //ahora Y mayuscula
    for(int i = 0; i < upperY.length; i++){

      data = data.replace(upperY[i], "Y");

    }

    //ahora Y minuscula
    for(int i = 0; i < lowerY.length; i++){

      data = data.replace(lowerY[i], "y");

    }

    //***************************************
    //ahora C mayuscula
    for(int i = 0; i < upperC.length; i++){

      data = data.replace(upperC[i], "C");

    }

    //ahora C minuscula
    for(int i = 0; i < lowerC.length; i++){

      data = data.replace(lowerC[i], "c");

    }

    data = data.replaceAll("Ñ","N");

    data = data.replaceAll("ñ","n");

    return data;

  }

  //Agregado 25/05/21
  private boolean verifyData(String data, String action){

    // action: replace -> r
    // action: verify -> v
    boolean existenceFlag = false;

    String[] dictionary;
    String[] combination;

    if(ADAbvoSpecial){      

      dictionary = new String[]{//preposiciones
        "antes", "dentro", "desde", "hace", "despues", "durante",
        "en", "hasta", "por", "sobre", "tras", "al", "para",
        //Articulos
        "el", "lo"
      };

      combination = new String[]{ 
        "dos", "da" , "do",
        "de" , "del", "la", "los", "san", "las"
      }; //Palabras de apellido compuesto


    }else{

      dictionary = new String[]{//preposiciones
        "antes", "de", "dentro", "desde", "hace", "despues", "durante",
        "en", "hasta", "por", "sobre", "tras", "al", "del", "para",
        //Articulos
        "el", "la", "lo", "los", "las"
      };

      combination =  new String[]{"dos", "da" , "do"}; //Palabras de apellido compuesto      

    }



    if(action.equalsIgnoreCase("r")){

      for(int i = 0 ; i < dictionary.length ; i++){

        if(data.equalsIgnoreCase(dictionary[i])){

          existenceFlag = true;

          break;
        }

      }

    }else if(action.equalsIgnoreCase("v")){

      for(int i = 0 ; i < combination.length ; i++){

        if(data.equalsIgnoreCase(combination[i])){

          existenceFlag = true;

          break;
        }

      }


    }


    return existenceFlag;
  }


