  private String getValueFromADAccount(Identity identity, String attributeToSearch){

    log.debug("Entrando a " + applicationName + "_Accounts_GetValueFromADAccount para " + identity.getName());
    log.debug("Con el atributo: " + attributeToSearch);

    Custom customObject = null;
    List mainList = new ArrayList();
    String principalKey = "";
    String customObjectName = "";
    Object newObject = null;
    String newValue = "";

    principalKey = "Valid Domains";
    customObjectName = applicationName + "_Valid_Domains";

    String val = "";/// Valor a regresar

    log.debug("Obteniendo lo dominios validos del custom object " + customObjectName );

    customObject = context.getObjectByName( Custom.class, 
                                           customObjectName);

    if (customObject != null) {

      newObject = customObject.get(principalKey);

      if(newObject != null) {

        if(newObject instanceof List) {

          log.debug("El CustomObject "+ customObjectName + " existe!");

          mainList = (List) customObject.get(principalKey);

          log.debug("Imprimiendo los dominios validos encontrados..");

          for(int i = 0 ; i < mainList.size() ; i++ ) {

            log.debug("Indice: " + i + " valor: " + mainList.get(i));

          }


          Identity manager = identity.getManager();
          Application app = context.getObjectByName(Application.class,applicationName);

          log.debug("Obteniendo el manager de la identidad...");

          if (manager !=null && app!=null){

            log.debug("Manager obtenido: " + manager.getName()); 

            IdentityService ids = new IdentityService(context);
            List links = ids.getLinks(manager,app);

            log.debug("Buscando las cuentas del aplicativo " + applicationName + " del manager...");

            if(links.isEmpty()){

              log.debug("El manager no tiene cuentas en el aplicativo " + applicationName);

            }else{

              if(links.size()==1){

                val = links.get(0).getNativeIdentity();

              }else if(links.size()>1){

                for(Link link : links){
                  if(!link.isDisabled() && (link.getAttributes()==null || 
                                                    (!link.getAttributes().getBoolean("privileged") && !link.getAttributes().getBoolean("inactive")))){
                    val=link.getNativeIdentity();
                    break;
                  }
                }

              }

              log.debug("manager en IIQ: " + val );

              //Aqui ya tenemos el valor de val
              log.debug("Buscamos el samaAccountName de la cuenta del manager...");

              String samAccountName = manager.getName(); //Aqui obtenemos el name, ya que es el samaAccountName en las cuentas

              log.debug("samaAccountName de la cuenta del manager: " + samAccountName);


              log.debug("Comenzamos a buscar entre los dominios...");

              String domainToSearch = "";

              for(int i = 0 ; i < mainList.size() ; i++ ) {

                String tempDomain = "";

                tempDomain = mainList.get(i);

                log.debug("Valor del dominio sin transformacion: " + tempDomain);

                int indexOf = -1;

                indexOf = tempDomain.indexOf("|");

                tempDomain = tempDomain.substring(indexOf + 1, tempDomain.length());

                log.debug("Valor del dominio con transformacion: " + tempDomain);

                if(val.contains(tempDomain)){

                  log.debug("Dominio encontrado!");

                  domainToSearch = tempDomain;

                  break;

                }


              }

              log.debug("Dominio a buscar en la configuraci n de la aplicacion: " + domainToSearch);

              log.debug("Leyendo dominios configurados en la aplicacion: " + applicationName );
              List listDomains = (List) app.getAttributeValue("domainSettings");

              log.debug( "Buscando datos de conexion al dominio de la cuenta... ");
              Hashtable env = new Hashtable();
              String domainFound = null;

              for(Map domainMap : listDomains){

                String appDomain = (String) domainMap.get("domainDN");

                if(domainToSearch.equalsIgnoreCase(appDomain)) {

                  log.debug("Dominio encontrado: " + appDomain);
                  domainFound = appDomain;

                  String authenticationType = (String) domainMap.get("authenticationType");
                  String port = ((String) domainMap.get("port"));
                  String server = ((List) domainMap.get("servers")).get(0).toString();
                  String user = (String) domainMap.get("user");
                  String credentials = context.decrypt( (String) domainMap.get("password") );
                  //Pruebas SSL DAA 160123
                  boolean sslCheck = domainMap.get("useSSL");
                  String sslSufix = "";
                  String url = "";                  

                  log.debug("Datos de conexion leidos para el dominio");
                  log.debug("authenticationType: " + authenticationType);
                  log.debug("port: " + port);
                  log.debug("server: " + server);
                  log.debug("user: " + user);

								  log.debug("SSL: " + sslCheck);

                  if(sslCheck){
                  sslSufix = "s";
                  }

                  url = "ldap"+sslSufix+"://" + server + ":" + port;
                  log.debug("URL: " + url);                   

                  env.put(Context.INITIAL_CONTEXT_FACTORY,"com.sun.jndi.ldap.LdapCtxFactory");
                  env.put(Context.PROVIDER_URL, url);
                  env.put(Context.SECURITY_PRINCIPAL, user);
                  env.put(Context.SECURITY_CREDENTIALS, credentials);
                  env.put(Context.SECURITY_AUTHENTICATION, authenticationType);

                  break;
                }
              }

              log.debug("Inicializando variables de busqueda"); 
              SearchControls searchCtls = new SearchControls();
              searchCtls.setReturningAttributes(Util.csvToArray(attributeToSearch));
              searchCtls.setSearchScope(SearchControls.SUBTREE_SCOPE);

              log.debug("Buscando cuenta en AD de " +samAccountName);
              LdapContext ctgxGC = new InitialLdapContext(env,null);
              String searchFilter = "(&(objectClass=user)(sAMAccountName=" + samAccountName + "))";
              NamingEnumeration answer = ctgxGC.search(domainFound, searchFilter, searchCtls);

              log.debug("Validando respuesta de la busqueda");

              if(answer.hasMoreElements()) {

                Attributes attrs = ( (SearchResult) answer.next() ).getAttributes();
                Attribute attr = attrs.get(attributeToSearch);

                if(attr != null){

                  dnFromAD = (String) attr.get();

                  log.debug("El valor de " + attributeToSearch + " para la cuenta en AD es: " + dnFromAD);

                  val = dnFromAD;

                }else{

                  log.debug("La cuenta no tiene valor en el atributo " + attributeToSearch + "!");

                  val = "";

                }


              }else {

                log.debug("No se encontro una cuenta de AD con sAMAccountName: " + samAccountName);

                val = "";

              }

              ctgxGC.close();


            }

          }else{

            log.debug("manager esta vacio!");

          }

        }else {

          log.debug("El objeto encontrado con la llave " + principalKey+ " no es una lista!");
          log.debug("El " + attributeToSearch + " no sera insertado!");

        }


      }else {

        log.debug("El valor "+ principalKey+ " no existe como llave en el CustomObject " + customObjectName +"!");
        log.debug("El " + attributeToSearch + " no sera insertado!");
      }

    }else {

      log.debug("El CustomObject "+ customObjectName + " no existe o esta vacio!");
      log.debug("El " + attributeToSearch + " no sera insertado!");

    }

    log.debug(attributeToSearch + ": " + val );

    log.debug("Saliendo de " + applicationName + "_Accounts_GetValueFromADAccount para " + identity.getName());

    return val;

  }

  private String getValueFromCountryData(Identity identity, String inputKey){


    log.debug("Entrando a getValueFromCountryData: "+inputKey);

    Map mainMap = new HashMap();
    String principalKey = "";
    Object newObject = null;
    Custom customObject = null;
    String customObjectName = "";
    String newValue;

    principalKey = "mexico";

      //identity.getStringAttribute("Pais");

    principalKey = removeAccents(principalKey.toLowerCase());

    customObjectName = "BancoBase-Custom-CountryData";

    log.debug("principalKey: "+principalKey);

    customObject = context.getObjectByName( Custom.class,customObjectName);

    if(customObject != null){

      log.debug("customObject");

      newObject = customObject.get(principalKey);

      if(newObject != null){

        log.debug("newObject");

        if(newObject instanceof Map){

          log.debug("newObject instanceof Map");

          mainMap = (Map) customObject.get(principalKey);

          String key = inputKey;
          Object value = null;

          value = mainMap.get(key);

          if(value != null){

            newValue = value.toString();

            log.debug("newValue: "+newValue);

          }

        }

      }

    }
    log.debug("Saliendo de getValueFromCountryData");

    return newValue;

  }

  private String getValueFromCountryDataMapping(Identity identity, String customObjectName){

    log.debug("Entrando a getValueFromCountryDataMapping");

    log.debug("customObjectName: "+customObjectName);
    Custom customObject = null;
    sailpoint.object.Attributes attributes = null;
    Map mainMap = new HashMap();

    String foundValue = "";

    customObject = context.getObjectByName( Custom.class, customObjectName);

    if(customObject != null){

      attributes = customObject.getAttributes();
      mainMap = attributes.getMap();

      Map sortedMainMap = new TreeMap(mainMap);

      for(Map.Entry entry : sortedMainMap.entrySet()){

        String key = "";
        String value = "";
        String[] arrayKey = null;

        key = entry.getKey();
        value = entry.getValue();

        int indexOfcharacter = 0;
        indexOfcharacter = key.indexOf("|");

        key = key.substring(indexOfcharacter + 1,key.length());

        arrayKey = key.split("[|]");

        int firstCounter = 0;
        int secondCounter = 0;

        secondCounter = arrayKey.length;

        for(int i = 0 ; i < arrayKey.length ; i++) {

          String tempKey = "";
          String tempValue = "";
          String identityValue = "";

          String[] tempKeys = null;

          tempKeys = arrayKey[i].split("[:]");

          tempKey = tempKeys[0];
          tempValue = tempKeys[1];

          identityValue = identity.getStringAttribute(tempKey);

          log.debug("identityValue: "+identityValue);

          if(identityValue != null){

            if(identityValue.equalsIgnoreCase(tempValue)){

              firstCounter++;

            }

          }

        }

        if(firstCounter == secondCounter){

          foundValue = value;



          break;

        }

      }

    }

    if(foundValue == null){

      foundValue = "";

    }
    log.debug("foundValue: "+foundValue);

    log.debug("Entrando a getValueFromCountryDataMapping");

    return foundValue;


  }

   public String removeAccents(String text) {
    return text == null ? null :
        Normalizer.normalize(text, Form.NFD)
            .replaceAll("\\p{InCombiningDiacriticalMarks}+", "");
	}


